insert into public.hans_products (id, doc) values
  ('HP-1', $j${"id":"HP-1","name":"Reusable sanitary pads (pack of 3)","category":"menstrual","variants":[{"sku":"RSP-REG","label":"Regular","price":350},{"sku":"RSP-HVY","label":"Heavy flow","price":380},{"sku":"RSP-NGT","label":"Night","price":420}],"stock":"available","education":{"use":"Place the pad on underwear with the soft side up and fasten the wings. Change every 4 to 6 hours or when full. Rinse in cold water first, wash with mild soap, dry fully in the sun. Lasts 12 to 24 months with care.","safety":"Do not use bleach. Dry completely before storing. Stop using and consult a health worker if you notice irritation."},"audioKey":"edu_pads"}$j$::jsonb),
  ('HP-2', $j${"id":"HP-2","name":"Period underwear","category":"menstrual","variants":[{"sku":"PU-S","label":"S","price":550},{"sku":"PU-M","label":"M","price":550},{"sku":"PU-L","label":"L","price":550},{"sku":"PU-XL","label":"XL","price":580}],"stock":"available","education":{"use":"Wear like normal underwear for light to medium days or with a pad on heavy days. Rinse in cold water after use, machine or hand wash, air dry.","safety":"Do not iron or tumble dry. Replace when the absorbent layer thins."},"audioKey":"edu_underwear"}$j$::jsonb),
  ('HP-3', $j${"id":"HP-3","name":"Adult diapers","category":"adult-care","variants":[{"sku":"AD-M","label":"M","price":620},{"sku":"AD-L","label":"L","price":660},{"sku":"AD-XL","label":"XL","price":700}],"stock":"available","education":{"use":"Check size by waist measurement. Change promptly when wet to protect the skin. Clean and dry the skin at each change.","safety":"Seek a health worker if you notice redness, sores or fever."},"audioKey":"edu_adult"}$j$::jsonb),
  ('HP-4', $j${"id":"HP-4","name":"Incontinence pads","category":"adult-care","variants":[{"sku":"IP-STD","label":"Standard (pack of 10)","price":300}],"stock":"limited","education":{"use":"Fix inside close-fitting underwear. Change when wet.","safety":"Not for use as a wound dressing."},"audioKey":"edu_incont"}$j$::jsonb),
  ('HP-5', $j${"id":"HP-5","name":"Washable bed protector","category":"adult-care","variants":[{"sku":"BP-90","label":"90 x 75 cm","price":480}],"stock":"available","education":{"use":"Place absorbent side up under the person. Wash at 60 degrees, air dry.","safety":"Replace if the waterproof layer cracks."},"audioKey":"edu_bed"}$j$::jsonb)
