insert into public.kb (id, doc) values
  ('KB-1', $j${"id":"KB-1","tags":["emergency","danger","signs"],"version":"1.0","approvedBy":"Clinical safety group (demo)","approvedAt":"2026-09-01","source":"WHO IMAI/IMCI danger signs, general guidance","title":{"en":"When is it an emergency?","fr":"Quand est-ce une urgence ?"},"body":{"en":"Call emergency services or go to the nearest emergency-capable facility now if there is: heavy bleeding, chest pain or pressure, difficulty breathing, unconsciousness or confusion, seizure, severe injury or burn, a suspected stroke (face drooping, arm weakness, speech difficulty), poisoning, severe abdominal pain in pregnancy, or thoughts of harming yourself. Do not wait for an online reply.","fr":"Appelez les urgences ou allez à l'établissement d'urgence le plus proche en cas de : saignement abondant, douleur ou pression thoracique, difficulté à respirer, perte de connaissance ou confusion, convulsions, blessure ou brûlure grave, suspicion d'AVC (visage affaissé, faiblesse du bras, trouble de la parole), empoisonnement, douleur abdominale sévère pendant la grossesse, ou pensées d'automutilation. N'attendez pas une réponse en ligne."}}$j$::jsonb),
  ('KB-2', $j${"id":"KB-2","tags":["period","pads","menstrual","wash","han's"],"version":"1.0","approvedBy":"Han's With Care (demo)","approvedAt":"2026-09-01","source":"Han's With Care product guidance","title":{"en":"Using and washing reusable pads","fr":"Utiliser et laver les serviettes réutilisables"},"body":{"en":"Change a reusable pad every 4 to 6 hours or when full. Rinse in cold water until the water runs clear, wash with mild soap, rinse again and dry fully, ideally in sunlight. Store dry. Pads last 12 to 24 months. Periods that are very heavy (soaking a pad every hour), last more than 7 days, or come with severe pain or fainting should be discussed with a health worker.","fr":"Changez la serviette toutes les 4 à 6 heures ou quand elle est pleine. Rincez à l'eau froide jusqu'à ce que l'eau soit claire, lavez au savon doux, rincez et séchez complètement, idéalement au soleil. Rangez au sec. Durée de vie 12 à 24 mois. Des règles très abondantes (une serviette trempée chaque heure), de plus de 7 jours, ou accompagnées de fortes douleurs ou d'évanouissements doivent être discutées avec un soignant."}}$j$::jsonb),
  ('KB-3', $j${"id":"KB-3","tags":["pregnancy","maternal","antenatal","danger"],"version":"1.0","approvedBy":"Clinical safety group (demo)","approvedAt":"2026-09-01","source":"WHO antenatal care recommendations (general)","title":{"en":"Pregnancy danger signs","fr":"Signes de danger pendant la grossesse"},"body":{"en":"Seek care immediately for vaginal bleeding, severe headache with blurred vision, fits, high fever, severe abdominal pain, the waters breaking before 37 weeks, the baby moving much less, or labour lasting more than 12 hours. Attend at least 8 antenatal contacts and deliver with a skilled attendant.","fr":"Consultez immédiatement en cas de saignement vaginal, forts maux de tête avec vision trouble, convulsions, forte fièvre, douleur abdominale sévère, perte des eaux avant 37 semaines, bébé qui bouge beaucoup moins, ou travail de plus de 12 heures. Faites au moins 8 consultations prénatales et accouchez avec un personnel qualifié."}}$j$::jsonb),
  ('KB-4', $j${"id":"KB-4","tags":["child","fever","diarrhoea","baby"],"version":"1.0","approvedBy":"Clinical safety group (demo)","approvedAt":"2026-09-01","source":"WHO IMCI general danger signs","title":{"en":"Sick child: when to go now","fr":"Enfant malade : quand consulter maintenant"},"body":{"en":"Take a child to a facility now if they cannot drink or breastfeed, vomit everything, have convulsions, are lethargic or unconscious, breathe fast or with difficulty, or have fever with a stiff neck or rash. For diarrhoea, give ORS and zinc and keep feeding; go now if there is blood in the stool or signs of dehydration.","fr":"Emmenez l'enfant maintenant s'il ne peut pas boire ou téter, vomit tout, convulse, est léthargique ou inconscient, respire vite ou difficilement, ou a de la fièvre avec raideur de la nuque ou éruption. Pour la diarrhée, donnez SRO et zinc et continuez à nourrir ; consultez immédiatement en cas de sang dans les selles ou de déshydratation."}}$j$::jsonb),
  ('KB-5', $j${"id":"KB-5","tags":["prescription","pharmacy","medicine","dispensing"],"version":"1.0","approvedBy":"Pharmacy adviser (demo)","approvedAt":"2026-09-01","source":"EFDA dispensing rules (general)","title":{"en":"Prescriptions and pharmacies on this platform","fr":"Ordonnances et pharmacies sur cette plateforme"},"body":{"en":"You can send a photo of a prescription to verified pharmacies to check availability and choose collection or delivery. Only a licensed pharmacist decides if a prescription is valid and what can be dispensed. Prescription-only medicines are never sold without a valid prescription, and the platform never substitutes medicines or gives dosing advice.","fr":"Vous pouvez envoyer la photo d'une ordonnance à des pharmacies vérifiées pour connaître la disponibilité et choisir retrait ou livraison. Seul un pharmacien agréé décide de la validité et de la délivrance. Les médicaments sur ordonnance ne sont jamais vendus sans ordonnance valide et la plateforme ne substitue jamais un médicament ni ne conseille de dosage."}}$j$::jsonb),
  ('KB-6', $j${"id":"KB-6","tags":["platform","how","account","privacy","free"],"version":"1.0","approvedBy":"Han's operations (demo)","approvedAt":"2026-09-01","source":"Platform terms","title":{"en":"How this platform works","fr":"Comment fonctionne la plateforme"},"body":{"en":"Browsing, emergency numbers and search are free and need no account. When you send a request or order, we ask only for a phone number, your consent and a location. Verified health workers respond from their own dashboard; you follow the status under My requests. The platform connects you to care; it does not replace a consultation.","fr":"La consultation, les numéros d'urgence et la recherche sont gratuits et sans compte. Pour une demande ou une commande, nous demandons seulement un numéro de téléphone, votre consentement et une localisation. Les soignants vérifiés répondent depuis leur tableau de bord ; suivez le statut dans Mes demandes. La plateforme vous met en relation avec des soins, elle ne remplace pas une consultation."}}$j$::jsonb),
  ('KB-7', $j${"id":"KB-7","tags":["mental","stress","sleep","anxiety","sad"],"version":"1.0","approvedBy":"Clinical safety group (demo)","approvedAt":"2026-09-01","source":"WHO mhGAP general guidance","title":{"en":"Mental wellbeing support","fr":"Soutien au bien-être mental"},"body":{"en":"Feeling low, anxious or unable to sleep for more than two weeks is a good reason to talk to a verified health worker. If you have thoughts of harming yourself, call emergency services or go to the nearest hospital now, and tell someone you trust.","fr":"Se sentir déprimé, anxieux ou ne pas dormir pendant plus de deux semaines justifie de parler à un soignant vérifié. En cas de pensées d'automutilation, appelez les urgences ou allez à l'hôpital le plus proche maintenant, et parlez-en à une personne de confiance."}}$j$::jsonb),
  ('KB-8', $j${"id":"KB-8","tags":["adult","incontinence","diaper","elderly","skin"],"version":"1.0","approvedBy":"Han's With Care (demo)","approvedAt":"2026-09-01","source":"Han's With Care product guidance","title":{"en":"Caring for an adult with incontinence","fr":"Prendre soin d'un adulte incontinent"},"body":{"en":"Change products promptly when wet, clean and dry the skin at each change, and check the skin daily. Redness that does not fade, sores, fever or pain when passing urine should be discussed with a health worker. New or sudden incontinence also deserves a consultation.","fr":"Changez rapidement les protections mouillées, nettoyez et séchez la peau à chaque change, et vérifiez la peau chaque jour. Une rougeur persistante, des plaies, de la fièvre ou des douleurs en urinant doivent être signalées à un soignant. Une incontinence nouvelle ou soudaine mérite aussi une consultation."}}$j$::jsonb)
