  ('RF-POISON', $j${"id":"RF-POISON","label":"poisoning","kw":{"en":["poison","swallowed","overdose","drank chemical"],"am":["መርዝ","ተመርዟል","መድሃኒት በብዛት"],"ti":["መርዚ","ተመሪዙ"],"om":["summii","summaa'e"],"so":["sun","sumoobay"],"fr":["poison","empoisonn","surdose","avalé"]}}$j$::jsonb),
  ('RF-SELF', $j${"id":"RF-SELF","label":"self-harm","kw":{"en":["kill myself","suicide","end my life","hurt myself","self-harm","want to die"],"am":["ራሴን ማጥፋት","ራሴን መግደል","መሞት እፈልጋለሁ"],"ti":["ነብሰይ ከጥፍእ","ክመውት እደሊ"],"om":["of ajjeesuu","du'uu barbaada"],"so":["is dilo","naftayda","dhiman rabaa"],"fr":["me suicider","me tuer","mettre fin à mes jours","me faire du mal"]}}$j$::jsonb),
  ('RF-LABOUR', $j${"id":"RF-LABOUR","label":"labour complication","kw":{"en":["in labour","in labor","waters broke","baby is coming","pregnant and bleeding","pregnant bleeding"],"am":["ምጥ","ውሃዬ ፈሰሰ","እርጉዝ ደም"],"ti":["ሕርሲ","ማይ ፈሲሱ"],"om":["ciniinsuu","bishaan cabe","ulfaa dhiiga"],"so":["foosha","biyaha dhacay","uur dhiig"],"fr":["en travail","perdu les eaux","enceinte et saigne"]}}$j$::jsonb),
  ('RF-INJURY', $j${"id":"RF-INJURY","label":"severe injury","kw":{"en":["accident","car crash","stabbed","shot","severe burn","broken bone","head injury","snake bite","snakebite"],"am":["አደጋ","መኪና ገጭቶኛል","ተወግቷል","ተቃጥሏል","እባብ ነደፈኝ"],"ti":["ሓደጋ","መኪና","ተወጊኡ","ተቓጺሉ","ተመን"],"om":["balaa konkolaataa","waraaname","gubate","bofa"],"so":["shil","baabuur","tooray","gubatay","abeeso"],"fr":["accident","brûlure grave","poignardé","fracture","morsure de serpent"]}}$j$::jsonb),
